/**
 * The patch defaults (#670): every value a patch may omit, and the bounds the
 * worklet clamps the tone, the feedback, the width, a Noise operator's
 * colour (windsor#362) and the Formant vowel (windsor#331) to. Two readers fill a
 * patch from this one table — `patchNormalise.ts` for the audio loop when a
 * `patch` message arrives, and `makePatch()` in the main thread's `patch/patch.ts` for the
 * editor, the tests and the console's knob defaults — so a knob cannot show
 * one default while the engine plays another. `patchDefaults.test.ts` pins
 * the two fills equal leaf for leaf for an empty partial.
 *
 * The one per-operator rule is carried as its inputs, not as four operator
 * rows: operator A (index 0) sounds at `LEAD_OPERATOR_LEVEL`, the others at
 * `OPERATOR_DEFAULTS.level` (`2026-09-23-670-one-patch-defaults-table`).
 *
 * Data only, like `modeIds.ts`, but for `driveOnByDefault`, the one default
 * that is read from other values (windsor#309), and `normaliseOpSyncs`, the
 * sync fields' one rule (windsor#646): it imports the two import-free id modules and
 * nothing else, never touches the worklet scope or the wave cache, is listed
 * in the engine project's `files` and is on the generators' pure side
 * because `audioConstants.ts` re-exports `OPERATOR_COUNT` from here. A
 * change to a value here is a render change: `fmProcessorGolden.test.ts`.
 */

import { DRIVE_SOFT, FILT_OFF, LFO_SINE, LOOP_NONE, MACRO_LINEAR } from './modeIds';
import { WAVE } from './waveIds';

/** Operators per voice — the length of `ops`, `lfo.toOp`, `lfo.toWidth` and `OP_NAMES`. */
const OPERATOR_COUNT = 4;

/** The envelope every operator gets; the pitch and filter envelopes override a few fields below. */
const ENVELOPE_DEFAULTS = {
  initLevel: 0,
  attackTime: 0.002,
  attackCurve: 0,
  peakLevel: 1,
  decayTime: 0.4,
  decayCurve: 0.5,
  sustainLevel: 0.7,
  releaseTime: 0.3,
  releaseCurve: 0.5,
  endLevel: 0,
  loopMode: LOOP_NONE,
  keyScale: 0,
};

/** The pitch envelope: a short blip that returns to pitch, not a held bend. */
const PITCH_ENV_DEFAULTS = { ...ENVELOPE_DEFAULTS, sustainLevel: 0, decayTime: 0.1 };

/** The filter envelope: decays to nothing, so an `envAmount` is a sweep, not an offset. */
const FILTER_ENV_DEFAULTS = { ...ENVELOPE_DEFAULTS, sustainLevel: 0 };

/** One operator, its envelope aside (`ENVELOPE_DEFAULTS`) and its level aside for operator A. */
const OPERATOR_DEFAULTS = {
  wave: WAVE.SINE,
  userPartials: null,
  ratio: 1,
  fixed: false,
  fixedHz: 100,
  detune: 0,
  level: 0,
  feedback: 0,
  /** The fraction of the period the wave is squeezed into; for PULSE, the duty. */
  width: 1,
  velSens: 0.4,
  levelKeyScale: 0,
  phase: 0,
  phaseFree: true,
  /**
   * The operator's own two-pole lowpass and highpass on its wave, in Hz
   * (windsor#362, every wave since windsor#590, `OP_FILTER_RANGE`); 0 is off.
   * `opTrack` moves both cutoffs by that many octaves an octave of the played
   * note from middle C (`OP_FILTER_TRACK_RANGE`); 0 holds them.
   */
  opLp: 0,
  opHp: 0,
  opTrack: 0,
  /**
   * Hard sync (windsor#646, record `2026-10-09-operator-hard-sync`): the
   * master whose own-phase wrap restarts this operator's phase, `'note'` or
   * an operator's letter, or `'off'`. `normaliseOpSyncs` keeps it valid.
   */
  sync: 'off' as OpSync,
};

/**
 * An operator's hard-sync master (windsor#646): off, the note itself, or an
 * operator by its letter (the letters are `OP_NAMES`, in operator order).
 * A string, so a later master is an additive value.
 */
const OP_SYNC_VALUES = ['off', 'note', 'A', 'B', 'C', 'D'] as const;
type OpSync = (typeof OP_SYNC_VALUES)[number];

/** The operator masters among `OP_SYNC_VALUES`, in operator order: `'A'` is operator 0. */
const OP_SYNC_OPERATORS: readonly OpSync[] = OP_SYNC_VALUES.slice(OP_SYNC_VALUES.indexOf('A'));

/**
 * The operators' sync fields as both fills keep them (windsor#646, record
 * decision 4): an unknown value is `'off'`, and so is every operator in a
 * cycle of operator masters, one synced to itself included. An operator
 * that leads into a cycle without being in it keeps its master, which is
 * then unsynced. The second rule read from other values, as
 * `driveOnByDefault` is, so the worklet and `makePatch()` agree.
 */
function normaliseOpSyncs(raw: readonly unknown[]): OpSync[] {
  const sync = raw.map((v): OpSync =>
    OP_SYNC_VALUES.includes(v as OpSync) ? (v as OpSync) : 'off',
  );
  const masterOf = (i: number): number => OP_SYNC_OPERATORS.indexOf(sync[i]!);
  const inCycle = sync.map((_, start) => {
    let at = start;
    for (let step = 0; step < sync.length; step++) {
      at = masterOf(at);
      if (at < 0) return false;
      if (at === start) return true;
    }
    return false;
  });
  return sync.map((v, i) => (inCycle[i] ? 'off' : v));
}

/** Operator A's level: the one operator an empty patch hears. */
const LEAD_OPERATOR_LEVEL = 1;

/** The patch's own scalars. */
const PATCH_DEFAULTS = {
  name: 'untitled',
  algorithm: 0,
  volume: 0.8,
  tone: 1,
  glide: 0,
  pitchEnvAmount: 0,
  pan: 0,
  panRandom: 0,
  panKey: 0,
  spread: 0,
  mono: false,
};

/**
 * The LFO, its per-operator depths aside (`LFO_TO_OP_DEFAULT` and
 * `LFO_TO_WIDTH_DEFAULT`, one per operator).
 */
const LFO_DEFAULTS = {
  shape: LFO_SINE,
  rate: 5,
  amount: 0,
  delay: 0,
  retrigger: false,
  /** The phase runs once from note-on and holds its end value. */
  oneShot: false,
  /** 0..1 instead of -1..1. */
  unipolar: false,
  toPitch: 0,
  modWheelDepth: 1,
};

/**
 * The second LFO: the first's defaults, but deaf to the mod wheel, so a fresh
 * LFO 2 is inert (record `2026-09-28-operator-width-pulse-and-a-second-lfo`).
 */
const LFO2_DEFAULTS = { ...LFO_DEFAULTS, modWheelDepth: 0 };

/** Each operator's LFO level-modulation depth. */
const LFO_TO_OP_DEFAULT = 0;

/** Each operator's LFO width-modulation depth. */
const LFO_TO_WIDTH_DEFAULT = 0;

/**
 * Each operator's LFO ratio-modulation depth (windsor#646), in octaves at
 * full LFO swing: 0 is off, and the worklet clamps it to `LFO_TO_RATIO_RANGE`.
 */
const LFO_TO_RATIO_DEFAULT = 0;
const LFO_TO_RATIO_RANGE = { min: -4, max: 4 };

/** The filter, its envelope aside (`FILTER_ENV_DEFAULTS`). */
const FILTER_DEFAULTS = {
  mode: FILT_OFF,
  cutoff: 8000,
  resonance: 0.707,
  slope24: false,
  envAmount: 0,
  modWheelDepth: 0,
  lfoAmount: 0,
  lfo2Amount: 0,
  keyTrack: 0,
  /** The Formant mode's vowel (windsor#331), `VOWEL_RANGE`: 0 a, 1 e, 2 i, 3 o, 4 u. */
  vowel: 0,
};

/**
 * The Formant mode's vowel, clamped here by the worklet: one unit per row of
 * `formantTables.ts`'s `FORMANT_VOWELS` (a to u), a fraction between two
 * rows. `patchDefaults.test.ts` pins the top to the table's last row.
 */
const VOWEL_RANGE = { min: 0, max: 4 };

/**
 * The voice's drive stage (windsor#300), between the carriers and the filter:
 * the input gain, the shape (`DRIVE_SHAPE`), a bias added before the shape and
 * a one-pole tone after it. Unity gain and no bias bypass the stage, so the
 * defaults are no drive at all (record `2026-10-01-voice-drive-stage`).
 * `on` is the console's switch (windsor#309): off, the stage costs nothing
 * whatever the other four say; a patch that omits it takes
 * `driveOnByDefault`, so a patch saved before the switch plays as it did.
 */
const DRIVE_DEFAULTS = {
  /** The input gain into the shaper, `DRIVE_GAIN_RANGE`; 1 is unity. */
  gain: 1,
  shape: DRIVE_SOFT,
  /** A DC offset added before the shaper, `DRIVE_BIAS_RANGE`. */
  bias: 0,
  /** The lowpass after the shaper, `DRIVE_TONE_RANGE`: 1 is open (bypassed). */
  tone: 1,
  /**
   * The stage's switch; omitted, it is `driveOnByDefault` of the gain and
   * bias. Last, here and in the worklet's fill (`patchNormalise.ts` says
   * why), so the four numbers keep the object shape they had before it.
   */
  on: false,
};

/**
 * The drive's input gain, clamped here by the worklet: the console's knob
 * reaches 6 and the library 1.6, so 64 is far past any musical use, and it
 * keeps `gain · x` finite for every carrier sum the voice can make.
 */
const DRIVE_GAIN_RANGE = { min: 0, max: 64 };

/**
 * The switch a patch that omits `drive.on` takes (windsor#309): on exactly
 * when the stage did something before the switch existed, a gain off unity
 * or a bias. Both fills call it with their own gain and bias, so the
 * worklet and `makePatch()` agree, and an old patch keeps its sound.
 */
function driveOnByDefault(gain: number, bias: number): boolean {
  return gain !== 1 || bias !== 0;
}

/** The drive's bias, clamped here by the worklet. */
const DRIVE_BIAS_RANGE = { min: -1, max: 1 };

/** The drive's tone, clamped here by the worklet: 0 is the darkest, 1 open. */
const DRIVE_TONE_RANGE = { min: 0, max: 1 };

/** `tone` is clamped here by the worklet: its floor keeps the anti-alias trim above silence. */
const TONE_RANGE = { min: 0.02, max: 1 };

/**
 * Operator self-feedback, clamped here by the worklet: bipolar (#529), the
 * negative (square) side to −1 and the positive (saw) side to 10 (windsor#842,
 * record `2026-10-16-operator-feedback-to-ten`). The value that matches
 * classic FM feedback `n` is `20.1 × 2^(n − 8)`, so the top, feedback 7, is
 * 10.05, rounded to 10. The same bounds are the voice target row's, the
 * catalog row's and the knob's.
 */
const FEEDBACK_RANGE = { min: -1, max: 10 };

/**
 * An operator's ratio as the console sets it and a ratio target moves it
 * (windsor#646): four octaves under the note to 24 times it. The floor is the
 * console's (`2026-09-18-618-console-ratio-floor-and-the-tools-lint-fence`);
 * the worklet does not clamp a patch's own ratio, and the voice target row
 * `ops.<i>.ratio` takes these bounds and its floor from here.
 */
const RATIO_RANGE = { min: 0.0625, max: 24 };

/** Operator width is clamped here by the worklet: 1 is the plain wave, the floor keeps a sliver of it. */
const WIDTH_RANGE = { min: 0.05, max: 1 };

/**
 * An operator's `opLp` and `opHp`, clamped here by the worklet: 0 is off, and
 * any cutoff above 0 sounds at `OP_FILTER_FLOOR_HZ` or more, key tracking
 * included (windsor#362, windsor#590, the ranges of
 * `docs/research/2026-10-01-tom-noise-colour-prototype/`).
 */
const OP_FILTER_RANGE = { min: 0, max: 20000 };

/** The lowest cutoff an operator filter that is on sounds at: the bottom of the knob's log sweep. */
const OP_FILTER_FLOOR_HZ = 20;

/** An operator's `opTrack`, clamped here by the worklet: the voice filter's Key Trk knob's range (windsor#590). */
const OP_FILTER_TRACK_RANGE = { min: -1, max: 2 };

/**
 * The patch's macros (windsor#559, record `2026-10-04-patch-macro-knobs`
 * decision 2): at most `MACROS_MAX`, each with at most `MACRO_MAPPINGS_MAX`
 * mappings. A patch has none by default, and a patch with none plays as it
 * did before macros. The voice target table gives each macro a row, so
 * `MACROS_MAX` is also the number of macro rows there.
 */
const MACROS_MAX = 8;
const MACRO_MAPPINGS_MAX = 8;

/** A macro's value, clamped here by the worklet: the macro row's own bounds. */
const MACRO_VALUE_RANGE = { min: 0, max: 1 };

/** A macro's own fields; its mappings default to none. */
const MACRO_DEFAULTS = { name: 'Macro', value: 0 };

/**
 * A mapping's fields but its `target`, which has no default: a mapping with
 * none is dropped. `min` and `max` are in the target's own units and are
 * clamped to its row's bounds by the worklet.
 */
const MACRO_MAPPING_DEFAULTS = { min: 0, max: 1, curve: MACRO_LINEAR, inverted: false };

export {
  DRIVE_BIAS_RANGE,
  DRIVE_DEFAULTS,
  DRIVE_GAIN_RANGE,
  DRIVE_TONE_RANGE,
  driveOnByDefault,
  ENVELOPE_DEFAULTS,
  FEEDBACK_RANGE,
  FILTER_DEFAULTS,
  FILTER_ENV_DEFAULTS,
  LEAD_OPERATOR_LEVEL,
  LFO2_DEFAULTS,
  LFO_DEFAULTS,
  LFO_TO_OP_DEFAULT,
  LFO_TO_RATIO_DEFAULT,
  LFO_TO_RATIO_RANGE,
  LFO_TO_WIDTH_DEFAULT,
  MACRO_DEFAULTS,
  MACRO_MAPPING_DEFAULTS,
  MACRO_MAPPINGS_MAX,
  MACRO_VALUE_RANGE,
  MACROS_MAX,
  normaliseOpSyncs,
  OP_FILTER_FLOOR_HZ,
  OP_FILTER_RANGE,
  OP_FILTER_TRACK_RANGE,
  OP_SYNC_OPERATORS,
  OP_SYNC_VALUES,
  OPERATOR_COUNT,
  OPERATOR_DEFAULTS,
  PATCH_DEFAULTS,
  PITCH_ENV_DEFAULTS,
  RATIO_RANGE,
  TONE_RANGE,
  VOWEL_RANGE,
  WIDTH_RANGE,
};
export type { OpSync };
